def base_request(**overrides):
    payload = {
        "nominal_capacity_ah": 100.0,
        "measurements": [
            {"timestamp_s": 0, "measured_capacity_ah": 100.0, "cumulative_discharge_ah": 0.0},
            {
                "timestamp_s": 100,
                "measured_capacity_ah": 90.0,
                "cumulative_discharge_ah": 100.0,
            },
